def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n >= 98 and sum(1 for a, b in history if b == 'D') > sum(1 for a, b in history if b == 'C'):
        return 'D'

    my_def = 0
    opp_def = 0
    opp_c = 0
    my_c = 0
    for a, b in history:
        if a == 'D':
            my_def += 1
        else:
            my_c += 1
        if b == 'D':
            opp_def += 1
        else:
            opp_c += 1

    aggressive = False
    for i in range(n):
        if history[i][0] == 'C' and history[i][1] == 'D':
            if i == 0 or history[i-1][0] == 'C':
                aggressive = True
                break

    retaliated = False
    non_retaliated = False
    if my_def > 0:
        observed = False
        non_ret = True
        for i in range(n - 1):
            if history[i][0] == 'D':
                observed = True
                if history[i+1][1] == 'D':
                    retaliated = True
                    non_ret = False
        if observed and non_ret:
            non_retaliated = True

    if aggressive:
        if opp_c == 0 or opp_def > opp_c * 2:
            return 'D'
        last_my, last_opp = history[-1]
        if last_opp == 'D':
            if last_my == 'D':
                return 'C'
            else:
                return 'D'
        else:
            if last_my == 'D':
                return 'C'
            else:
                return 'C'

    if non_retaliated:
        if opp_def == 0:
            return 'D'

    if retaliated:
        return 'C'

    if my_def == 0 and opp_def == 0:
        if n == 19:
            return 'D'
        return 'C'

    return 'C'
